/**
 * AppRegistry — Unit tests
 *
 * Tests for registerApp(), getRegistry(), and getApp().
 * Run with: npx vitest run 03_AppRegistry/registry.test.ts
 */

import { describe, it, expect, beforeEach, vi } from "vitest";
import {
  registerApp,
  getRegistry,
  getApp,
  _clearRegistry,
} from "./registry";
import type { AppRegistration } from "./types";

// ---------------------------------------------------------------------------
// Fixtures
// ---------------------------------------------------------------------------

const workoutApp: AppRegistration = {
  appId:    "workout",
  label:    "Workout",
  basePath: "/workout",
  order:    1,
  icon:     "fitness_center",
  desktopNav: [
    { id: "log",         label: "Log",         path: "/workout" },
    { id: "performance", label: "Performance",  path: "/workout/performance" },
    { id: "history",     label: "History",      path: "/workout/history" },
  ],
  mobilePrimaryNav: [
    { id: "log",         label: "Log",         path: "/workout" },
    { id: "performance", label: "Performance",  path: "/workout/performance" },
  ],
  secondaryMenu: [
    { id: "history",  label: "History",  path: "/workout/history" },
    { id: "settings", label: "Settings", path: "/workout/settings" },
  ],
};

const taskApp: AppRegistration = {
  appId:    "tasks",
  label:    "Tasks",
  basePath: "/tasks",
  order:    2,
  icon:     "task_alt",
  desktopNav: [
    { id: "inbox",    label: "Inbox",    path: "/tasks" },
    { id: "projects", label: "Projects", path: "/tasks/projects" },
  ],
  mobilePrimaryNav: [
    { id: "inbox", label: "Inbox", path: "/tasks" },
  ],
  secondaryMenu: [
    { id: "projects", label: "Projects", path: "/tasks/projects" },
    { id: "settings", label: "Settings", path: "/tasks/settings" },
  ],
};

// ---------------------------------------------------------------------------
// Setup
// ---------------------------------------------------------------------------

beforeEach(() => {
  _clearRegistry();
  vi.restoreAllMocks();
});

// ---------------------------------------------------------------------------
// Registration
// ---------------------------------------------------------------------------

describe("registerApp", () => {
  it("registers an application", () => {
    registerApp(workoutApp);
    expect(getApp("workout")).toEqual(workoutApp);
  });

  it("registers multiple applications", () => {
    registerApp(workoutApp);
    registerApp(taskApp);
    expect(getRegistry()).toHaveLength(2);
  });

  it("replaces previous registration on duplicate appId with a warning", () => {
    const warn = vi.spyOn(console, "warn");
    registerApp(workoutApp);

    const updated = { ...workoutApp, label: "Workout Updated" };
    registerApp(updated);

    expect(getApp("workout")?.label).toBe("Workout Updated");
    expect(warn).toHaveBeenCalledWith(
      expect.stringContaining('duplicate appId "workout"')
    );
  });

  it("trims mobilePrimaryNav to 2 items and moves overflow to secondaryMenu with a warning", () => {
    const warn = vi.spyOn(console, "warn");
    const app: AppRegistration = {
      ...workoutApp,
      mobilePrimaryNav: [
        { id: "log",         label: "Log",         path: "/workout" },
        { id: "performance", label: "Performance",  path: "/workout/performance" },
        { id: "history",     label: "History",      path: "/workout/history" },
      ],
      secondaryMenu: [],
    };

    registerApp(app);

    const registered = getApp("workout")!;
    expect(registered.mobilePrimaryNav).toHaveLength(2);
    expect(registered.secondaryMenu).toHaveLength(1);
    expect(registered.secondaryMenu[0].id).toBe("history");
    expect(warn).toHaveBeenCalledWith(
      expect.stringContaining("mobilePrimaryNav exceeds 2 items")
    );
  });
});

// ---------------------------------------------------------------------------
// Ordering
// ---------------------------------------------------------------------------

describe("getRegistry ordering", () => {
  it("orders apps by explicit order value ascending", () => {
    registerApp(taskApp);    // order: 2
    registerApp(workoutApp); // order: 1
    const ids = getRegistry().map(a => a.appId);
    expect(ids).toEqual(["workout", "tasks"]);
  });

  it("places apps without order after ordered apps", () => {
    const noOrder: AppRegistration = {
      ...workoutApp,
      appId: "nutrition",
      basePath: "/nutrition",
      order: undefined,
    };
    registerApp(noOrder);
    registerApp(taskApp);    // order: 2
    registerApp(workoutApp); // order: 1
    const ids = getRegistry().map(a => a.appId);
    expect(ids[0]).toBe("workout");
    expect(ids[1]).toBe("tasks");
    expect(ids[2]).toBe("nutrition");
  });
});

// ---------------------------------------------------------------------------
// Mobile nav overflow
// ---------------------------------------------------------------------------

describe("mobile nav overflow", () => {
  it("warns when total mobilePrimaryNav slots across apps exceed 4", () => {
    const warn = vi.spyOn(console, "warn");

    // workoutApp: 2 slots, taskApp: 1 slot = 3 total — no warning yet
    registerApp(workoutApp);
    registerApp(taskApp);

    const extraApp: AppRegistration = {
      ...workoutApp,
      appId:    "nutrition",
      basePath: "/nutrition",
      mobilePrimaryNav: [
        { id: "diary",   label: "Diary",   path: "/nutrition" },
        { id: "macros",  label: "Macros",  path: "/nutrition/macros" },
      ],
      secondaryMenu: [],
    };

    // 2 + 1 + 2 = 5 > 4 — overflow warning
    registerApp(extraApp);

    expect(warn).toHaveBeenCalledWith(
      expect.stringContaining("[PLATFORM GAP] Mobile navigation overflow")
    );
  });
});

// ---------------------------------------------------------------------------
// getApp
// ---------------------------------------------------------------------------

describe("getApp", () => {
  it("returns undefined for unknown appId", () => {
    expect(getApp("unknown")).toBeUndefined();
  });

  it("returns the registered app for a known appId", () => {
    registerApp(workoutApp);
    expect(getApp("workout")?.appId).toBe("workout");
  });
});

