/**
 * AppRegistry — Runtime registration store
 *
 * Maintains the ordered list of registered applications.
 * Applications call registerApp() at initialization; the shell reads getRegistry()
 * to derive all navigation rendering.
 *
 * This module has no domain logic and no side effects beyond maintaining the registry.
 */

import type { AppRegistration } from "./types";

// ---------------------------------------------------------------------------
// Internal state
// ---------------------------------------------------------------------------

const _registry: Map<string, AppRegistration> = new Map();

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

/** Maximum number of primary mobile navigation slots across all apps (1 reserved for launcher). */
const MOBILE_NAV_MAX_TOTAL = 5;
const MOBILE_NAV_LAUNCHER_SLOT = 1;
const MOBILE_NAV_APP_MAX = MOBILE_NAV_MAX_TOTAL - MOBILE_NAV_LAUNCHER_SLOT; // 4

/** Maximum mobilePrimaryNav items a single application may declare. */
const MOBILE_PRIMARY_NAV_PER_APP_MAX = 2;

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * Register an application with the shell.
 *
 * - Duplicate appId: logs a warning and replaces the previous registration.
 * - mobilePrimaryNav exceeding 2 items: logs a warning, trims to 2, excess moved to secondaryMenu.
 * - Global mobile nav slot overflow (>4 app slots total): logs a platform gap warning.
 */
export function registerApp(config: AppRegistration): void {
  if (_registry.has(config.appId)) {
    console.warn(
      `[AtlasShell] registerApp: duplicate appId "${config.appId}". ` +
        "Previous registration replaced."
    );
  }

  const sanitized = sanitizeRegistration(config);
  _registry.set(sanitized.appId, sanitized);

  checkMobileNavOverflow();
}

/**
 * Returns all registered applications ordered by:
 * 1. Explicit `order` value (ascending)
 * 2. Registration sequence (for apps without `order`)
 */
export function getRegistry(): AppRegistration[] {
  const entries = Array.from(_registry.values());
  return entries.sort((a, b) => {
    const aOrder = a.order ?? Infinity;
    const bOrder = b.order ?? Infinity;
    return aOrder - bOrder;
  });
}

/**
 * Returns the AppRegistration for a given appId, or undefined if not registered.
 */
export function getApp(appId: string): AppRegistration | undefined {
  return _registry.get(appId);
}

/**
 * Clears all registrations. Used in tests only.
 * @internal
 */
export function _clearRegistry(): void {
  _registry.clear();
}

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

function sanitizeRegistration(config: AppRegistration): AppRegistration {
  let { mobilePrimaryNav, secondaryMenu } = config;

  if (mobilePrimaryNav.length > MOBILE_PRIMARY_NAV_PER_APP_MAX) {
    console.warn(
      `[AtlasShell] registerApp "${config.appId}": mobilePrimaryNav exceeds ` +
        `${MOBILE_PRIMARY_NAV_PER_APP_MAX} items. ` +
        `${mobilePrimaryNav.length - MOBILE_PRIMARY_NAV_PER_APP_MAX} item(s) moved to secondaryMenu.`
    );
    const overflow = mobilePrimaryNav.slice(MOBILE_PRIMARY_NAV_PER_APP_MAX);
    mobilePrimaryNav = mobilePrimaryNav.slice(0, MOBILE_PRIMARY_NAV_PER_APP_MAX);
    secondaryMenu = [...overflow, ...secondaryMenu];
  }

  return { ...config, mobilePrimaryNav, secondaryMenu };
}

function checkMobileNavOverflow(): void {
  const totalAppSlots = Array.from(_registry.values()).reduce(
    (sum, app) => sum + app.mobilePrimaryNav.length,
    0
  );

  if (totalAppSlots > MOBILE_NAV_APP_MAX) {
    console.warn(
      `[AtlasShell] [PLATFORM GAP] Mobile navigation overflow: ` +
        `${totalAppSlots} app primary nav items across registered apps exceeds ` +
        `the ${MOBILE_NAV_APP_MAX}-slot maximum (${MOBILE_NAV_MAX_TOTAL} total minus launcher). ` +
        "Only the first registered apps' items will be shown in mobile bottom nav."
    );
  }
}

