/**
 * AppRegistry — Application Registration Contract
 *
 * This file is the authoritative TypeScript definition of the AppRegistration
 * interface. Applications in 03_Application import this type to declare their
 * navigation configuration.
 *
 * Rules:
 * - appId must be unique across all registered applications.
 * - basePath must be unique and must start with "/".
 * - mobilePrimaryNav is capped at 2 items per application.
 * - All NavItem.path values must start with AppRegistration.basePath.
 * - Do not extend or override this interface locally in applications.
 *   Propose changes here when the contract needs to change.
 */

/**
 * A single navigation entry pointing to a page within an application.
 */
export interface NavItem {
  /** Stable identifier used as a route segment. Lowercase, hyphen-separated. */
  id: string;

  /** Human-readable label shown in navigation. */
  label: string;

  /**
   * Absolute path for this navigation entry.
   * Must start with the parent AppRegistration.basePath.
   */
  path: string;

  /**
   * Material Symbols Rounded icon name (optional).
   * Example: "fitness_center", "task_alt", "insights"
   * Reference: https://fonts.google.com/icons
   */
  icon?: string;
}

/**
 * The registration contract an application provides to the Atlas Shell.
 *
 * Applications call registerApp(config) once at module initialization.
 * The shell renders all navigation from this config — no shell code changes
 * are needed when a new application is added.
 */
export interface AppRegistration {
  /**
   * Stable, unique application identifier.
   * Lowercase, hyphen-separated. Never changes after initial registration.
   * Examples: "workout", "task-tracker", "nutrition"
   */
  appId: string;

  /**
   * Human-readable application name shown in the launcher and navigation.
   * Example: "Workout", "Tasks", "Nutrition"
   */
  label: string;

  /**
   * Absolute base path for this application.
   * All application routes must be nested under this path.
   * Example: "/workout", "/tasks"
   */
  basePath: string;

  /**
   * Display order in the launcher and global navigation.
   * Lower numbers appear first. Applications without an order value
   * are appended after ordered entries in registration sequence.
   */
  order?: number;

  /**
   * Material Symbols Rounded icon name for the application-level nav entry.
   * Shown in the sidebar global nav and the launcher.
   */
  icon?: string;

  /**
   * Full navigation list for the desktop sidebar.
   * All pages the application exposes, in display order.
   * Rendered as Level 2 local navigation below the global app switcher.
   */
  desktopNav: NavItem[];

  /**
   * Navigation items promoted to primary mobile navigation.
   * Maximum 2 items per application (shell enforces this limit).
   * These appear as dedicated slots in the mobile bottom navigation bar.
   * Items beyond 2 are moved to secondaryMenu with a console warning.
   *
   */
  mobilePrimaryNav: NavItem[];

  /**
   * Secondary navigation items shown in the More menu.
   * These are pages not promoted to primary navigation.
   * Always accessible regardless of screen size.
   */
  secondaryMenu: NavItem[];
}
